items.body:
这是一个**完整可用**的插件。整份拷走, 改 id / title / html / css / js 就是你自己的包 —— 别从零开始拼, 从这个改。

放到 `../../packages.local/hello_counter.json`(路径就是你 cwd 往上两级), 落盘几秒后自动装上。

```json
{
  "type": "ui",
  "id": "hello_counter",
  "version": "1",
  "title": "点一下加一(最小例子)",
  "commands": {
    "say": {
      "primitive": "speak",
      "summary": "把当前的数字念出来",
      "params": {
        "text": {
          "type": "text",
          "required": true
        }
      }
    }
  },
  "html": "<div class="box">
  <div class="n" id="n">0</div>
  <button id="add">点我 +1</button>
  <button id="say">念出来</button>
  <div class="err" id="err"></div>
</div>",
  "css": ".box{padding:16px;text-align:center;background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:var(--radius)}
.n{font-size:40px;font-weight:700;margin-bottom:12px;color:var(--text)}
button{font:inherit;padding:6px 14px;margin:0 4px;cursor:pointer}
.err{color:var(--danger);margin-top:10px;min-height:1em}",
  "js": "// 沙箱里没有 require / fetch / eval / localStorage, 也够不到宿主页面。
// 对外只有 butlerUI 这一个对象: onInit / onPush / call / setState / resize。
// 🔴 不用喊 ready —— 那是沙箱桥自己发的, butlerUI 上根本没有这个方法。
var n = 0;
var nEl = document.getElementById('n');
var errEl = document.getElementById('err');

// 开窗时宿主把上次存的东西带回来
butlerUI.onInit(function (d) {
  n = (d && d.state && d.state.n) || 0;
  paint();
});

// 🔴 setState 失败是静默的, 错误只从 onPush 回来。不接这个就永远不知道存没存上。
butlerUI.onPush(function (d) {
  if (d && d.error) errEl.textContent = String(d.error);
});

function paint() {
  nEl.textContent = n;
  butlerUI.resize(document.body.scrollHeight);
}

document.getElementById('add').addEventListener('click', function () {
  n += 1;
  paint();
  butlerUI.setState({ n: n });
});

document.getElementById('say').addEventListener('click', function () {
  // 命令名一律带包 id 前缀: 声明里写 say, 调用时是 hello_counter.say
  butlerUI.call('hello_counter.say', { text: '现在是 ' + n });
});
"
}
```

## 这个例子专门示范了四件最容易做错的事

| 做对的地方 | 做错会怎样 |
|---|---|
| 颜色**全走 `var(--…)`**, 底色文字色成对给 | 自己编十六进制 → 深底深字/白底白字, 不报错只有肉眼看得见 |
| **没有** 调 ready | 去找 `butlerUI.ready()` 会发现根本没这个方法 —— 它是沙箱桥自己发的 |
| 用 `onInit` 拿回上次的 state | 在顶层直接读 DOM 也行, 但拿不到宿主带回来的 state |
| 接了 `onPush` 显示 error | setState 超 64K 是**静默**失败, 不接就永远看不见 |
| 调用写全名 `hello_counter.say` | 声明里写 `say`, 但宿主一律加包 id 前缀, 写短名调不到 |

另外: `resize` 每次内容变了都喊一声, 不然框子是死高度。

body_i18n.ja:
これは**完全に動作する**UI パッケージだ。全体をコピーして、id / title / html / css / js を変えるだけでお前自身のパッケージになる —— ゼロから組むな、これをベースに修正しろ。

`../../packages.local/hello_counter.json` に置く(パスは cwd から上 2 階層)。ディスクに落ちた数秒後に自動で装荷される。

```json
{
  "type": "ui",
  "id": "hello_counter",
  "version": "1",
  "title": "クリックで +1(最小例)",
  "commands": {
    "say": {
      "primitive": "speak",
      "summary": "今の数字を読み上げる",
      "params": {
        "text": {
          "type": "text",
          "required": true
        }
      }
    }
  },
  "html": "<div class="box">
  <div class="n" id="n">0</div>
  <button id="add">押して +1</button>
  <button id="say">読み上げ</button>
  <div class="err" id="err"></div>
</div>",
  "css": ".box{padding:16px;text-align:center;background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:var(--radius)}
.n{font-size:40px;font-weight:700;margin-bottom:12px;color:var(--text)}
button{font:inherit;padding:6px 14px;margin:0 4px;cursor:pointer}
.err{color:var(--danger);margin-top:10px;min-height:1em}",
  "js": "// サンドボックスには require / fetch / eval / localStorage がなく、ホストページにも届かない。
// 外から触れるのは butlerUI ただ一つ: onInit / onPush / call / setState / resize。
// 🔴 ready を呼ぶ必要はない —— あれはサンドボックスブリッジが自分で送るもので、butlerUI にそんなメソッドは無い。
var n = 0;
var nEl = document.getElementById('n');
var errEl = document.getElementById('err');

// 開いた時にホストが前回保存した物を返してくる
butlerUI.onInit(function (d) {
  n = (d && d.state && d.state.n) || 0;
  paint();
});

// 🔴 setState の失敗は無言。エラーは onPush からしか返らない。受け取らないと保存できたか永遠に分からない。
butlerUI.onPush(function (d) {
  if (d && d.error) errEl.textContent = String(d.error);
});

function paint() {
  nEl.textContent = n;
  butlerUI.resize(document.body.scrollHeight);
}

document.getElementById('add').addEventListener('click', function () {
  n += 1;
  paint();
  butlerUI.setState({ n: n });
});

document.getElementById('say').addEventListener('click', function () {
  // コマンド名には必ずパッケージ id の接頭辞が付く: 宣言では say、呼ぶ時は hello_counter.say
  butlerUI.call('hello_counter.say', { text: '今は ' + n });
});
"
}
```

## この例は最もよくやる間違い 4 つを示している

| 正しいやり方 | 間違うとどうなるか |
|---|---|
| 色は全部 `var(--…)` で、背景文字色をペアで指定 | 16 進数を自分で編む → 暗い背景に暗い字/白背景に白字、エラーなしで目に見えるだけ |
| **`ready` を呼ばない** | `butlerUI.ready()` を探すと、実はメソッドがない —— 沙箱ブリッジが自分で送るやつだ |
| `onInit` で前回の state をもらう | トップレベルで直に DOM を読んでもいいが、ホストが持ってきた state がとれない |
| `onPush` を受け取ってエラーを表示 | setState が 64K を超えるのは**静か**に失敗し、受け取らないと永遠に見えない |
| 完全な名前 `hello_counter.say` で呼ぶ | 宣言では `say` だが、ホストは必ずパッケージ id を先頭に付ける。短い名前では呼べない |

それと: `resize` は内容が変わるたびに叫べ、さもないと枠の高さは固定だ。

